using UnityEngine;
namespace Underwater {
// Sample the authored skeleton with species-specific contraction and recovery timing.
[DefaultExecutionOrder(30)]
public sealed class JellyReferenceMotion:MonoBehaviour {
 public bool comb;public Animation player;public float phase;
 Renderer[] combSkins;MaterialPropertyBlock combBlock;AnimationState combState;Transform bell;Vector3 bellScale;int bellAxis=1;float clock;bool ready;
 public void Initialize(){if(ready)return;ready=true;if(!player)player=GetComponentInChildren<Animation>();if(!player||!player.clip)return;player.enabled=false;player.playAutomatically=false;player.clip.SampleAnimation(player.gameObject,0);if(comb){combSkins=player.GetComponentsInChildren<Renderer>();combBlock=new MaterialPropertyBlock();if(Application.isPlaying){player.enabled=true;player.cullingType=AnimationCullingType.AlwaysAnimate;player.wrapMode=WrapMode.Loop;player.Play(player.clip.name);combState=player[player.clip.name];combState.speed=0;}}else{bell=System.Array.Find(player.GetComponentsInChildren<Transform>(),t=>t.name=="B_71");if(bell){bellScale=bell.localScale;var skins=player.GetComponentsInChildren<SkinnedMeshRenderer>();var crown=System.Array.Find(skins,s=>s.name=="Object_8");var trailing=System.Array.Find(skins,s=>s.name=="Object_7");if(crown&&trailing){var up=bell.InverseTransformDirection(crown.bounds.center-trailing.bounds.center).normalized;bellAxis=Mathf.Abs(up.x)>Mathf.Abs(up.y)?(Mathf.Abs(up.x)>Mathf.Abs(up.z)?0:2):(Mathf.Abs(up.y)>Mathf.Abs(up.z)?1:2);}}}}
 public void Step(float dt){Initialize();if(!player||!player.clip)return;clock+=dt;if(comb){float sampleTime=Mathf.Repeat(clock/4.8f+phase,1)*player.clip.length;if(combState!=null){combState.time=sampleTime;player.Sample();}else player.clip.SampleAnimation(player.gameObject,sampleTime);foreach(var skin in combSkins){skin.GetPropertyBlock(combBlock);combBlock.SetFloat("_CombTime",clock);combBlock.SetFloat("_CombPhase",phase*Mathf.PI*2);skin.SetPropertyBlock(combBlock);}}else{float t=Mathf.Repeat(clock/1.8f+phase,1);float sample=t<.22f?Mathf.SmoothStep(0,.5f,t/.22f):Mathf.SmoothStep(.5f,1,(t-.22f)/.78f);if(bell)bell.localScale=bellScale;player.clip.SampleAnimation(player.gameObject,sample*player.clip.length);if(bell){float contraction=t<.22f?Mathf.SmoothStep(0,1,t/.22f):1-Mathf.SmoothStep(0,1,(t-.22f)/.78f);var scale=bell.localScale;for(int axis=0;axis<3;axis++)if(axis!=bellAxis)scale[axis]*=1-.15f*contraction;bell.localScale=scale;}}}
 void LateUpdate(){var d=Diver.Instance;if(d&&d.MenuOpen)return;Step(Mathf.Min(Time.deltaTime,.05f));}
}
}
